// Out of scope by Maria's instruction 2026-08-27: HTML projects and both
// Personality projects.
function outOfScope(name) {
  const n = String(name || '');
  if (/html/i.test(n)) { return 'html_project'; }
  if (/^\s*personality/i.test(n)) { return 'personality_project'; }
  return null;
}
const out = [];
const excluded = [];
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    const why = outOfScope(p.name);
    if (why) { excluded.push(p.name + ' (' + why + ')'); continue; }
    out.push({ json: {
      project_id: p.project_id,
      project_name: p.name,
      base_lang: (p.base_language_iso || 'en').toLowerCase()
    }});
  }
}
for (const o of out) { o.json.excluded_projects = excluded; }
return out;

const PER = 500;
const reqs = $('Build Count Requests').all();
const res = $input.all();
const out = [];
const failed = [];
let excluded = [];
const before = {};

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (meta.excluded_projects && meta.excluded_projects.length > excluded.length) { excluded = meta.excluded_projects; }

  const r = res[i].json || {};
  const hdr = r.headers || {};
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name); continue; }
  before[meta.project_name] = total;
  if (total === 0) { continue; }

  const pages = Math.ceil(total / PER);
  for (let p = 1; p <= pages; p++) {
    out.push({ json: {
      project_id: meta.project_id,
      project_name: meta.project_name,
      base_lang: meta.base_lang,
      page: p
    }});
  }
}
for (const o of out) {
  o.json.failed = failed;
  o.json.excluded_projects = excluded;
  o.json.count_before = before;
}
if (out.length === 0) {
  out.push({ json: { project_id: null, page: 0, failed: failed, excluded_projects: excluded, count_before: before } });
}
return out;

const MAX_WRITES = 60;
const PSEUDO = ['ps', 'pst'];

function isPseudo(iso) {
  const s = String(iso || '').toLowerCase();
  return PSEUDO.indexOf(s) !== -1 || s.indexOf('pseudo') !== -1;
}
function reject(s) {
  if (typeof s !== 'string' || s === '') { return 'empty'; }
  if (!/ {2,}/.test(s)) { return 'no_double_space'; }
  if (/[\u00A0\u202F\u2009\u200A\u2007\u2060\uFEFF]/.test(s)) { return 'nbsp_or_thin_space'; }
  if (/[<>&]/.test(s)) { return 'markup_or_entity'; }
  if (/[\n\r\t\v\f]/.test(s)) { return 'real_newline_or_tab'; }
  if (/\\[nrtvf]/.test(s)) { return 'escaped_newline'; }
  if (/^\s|\s$/.test(s)) { return 'edge_whitespace'; }
  if (/[%{}\[\]]/.test(s)) { return 'placeholder_char'; }
  if (s.indexOf('$t(') >= 0) { return 'i18n_call'; }
  return null;
}
function verify(before, after) {
  if (after === before) { return 'no_change'; }
  if (/ {2,}/.test(after)) { return 'still_has_double'; }
  if (before.replace(/ /g, '') !== after.replace(/ /g, '')) { return 'changed_non_space'; }
  if (before.length <= after.length) { return 'did_not_shrink'; }
  return null;
}

const reqs = $('Build Page Requests').all();
const res = $input.all();
const meta0 = (reqs[0] || { json: {} }).json;
const seenKey = {};
const seenTr = {};
const out = [];
const readFail = [];
const rejected = {};
let keysSeen = 0;
let translationsSeen = 0;
function bump(k) { rejected[k] = (rejected[k] || 0) + 1; }

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  if (!meta.project_id) { continue; }

  const r = res[i].json || {};
  if (r.statusCode !== 200) { readFail.push(meta.project_name + ' p' + meta.page); continue; }

  for (const k of ((r.body && r.body.keys) ? r.body.keys : [])) {
    if (k.is_archived) { bump('archived_key'); continue; }
    const dk = meta.project_id + '#' + k.key_id;
    if (seenKey[dk]) { continue; }
    seenKey[dk] = 1;
    keysSeen++;

    for (const tr of (k.translations || [])) {
      translationsSeen++;
      const before = tr.translation;
      if (typeof before !== 'string') { bump('plural_object'); continue; }
      const iso = String(tr.language_iso || '').toLowerCase();
      if (isPseudo(iso)) { bump('pseudo_locale'); continue; }
      if (iso === meta.base_lang) { bump('source_language'); continue; }
      if (tr.is_reviewed) { bump('reviewed'); continue; }
      const why = reject(before);
      if (why) { bump(why); continue; }
      const after = before.replace(/ {2,}/g, ' ');
      const bad = verify(before, after);
      if (bad) { bump('verify_' + bad); continue; }
      if (seenTr[tr.translation_id]) { continue; }
      seenTr[tr.translation_id] = 1;

      let kn = k.key_name;
      if (kn && typeof kn === 'object') { kn = kn.web || kn.other || kn.ios || kn.android || String(k.key_id); }

      out.push({ json: {
        project: meta.project_name,
        project_id: meta.project_id,
        key: String(kn),
        translation_id: tr.translation_id,
        lang: iso,
        spaces_removed: before.length - after.length,
        before: before,
        after: after,
        excluded_projects: meta0.excluded_projects || [],
        count_before: meta0.count_before || {}
      }});
    }
  }
}

if (readFail.length > 0) {
  throw new Error('Aborting before any write: could not read ' + readFail.join(', ') + '. A partial read would produce a partial fix.');
}
if (out.length > MAX_WRITES) {
  throw new Error('Aborting before any write: plan is ' + out.length + ' rows, above the ' + MAX_WRITES + ' cap. Check the scope filters.');
}
// An empty plan must never look like a clean success.
if (out.length === 0) {
  throw new Error('Plan is empty, nothing written. pages=' + res.length + ' keys=' + keysSeen + ' translations=' + translationsSeen + ' rejected=' + JSON.stringify(rejected));
}
return out;

const plans = $('Build Write Plan').all();
const res = $input.all();
const ok = [];
const bad = [];
const mismatch = [];
const byProject = {};

for (let i = 0; i < res.length; i++) {
  const p = (plans[i] || { json: {} }).json;
  const r = res[i].json || {};
  const rec = {
    project: p.project, lang: p.lang, key: p.key,
    translation_id: p.translation_id, status: r.statusCode,
    before: p.before, after: p.after
  };
  if (r.statusCode === 200) {
    const returned = (r.body && r.body.translation) ? r.body.translation.translation : null;
    if (typeof returned === 'string' && returned !== p.after) {
      rec.returned = returned;
      mismatch.push(rec);
    } else {
      ok.push(rec);
    }
    if (!byProject[p.project]) { byProject[p.project] = 0; }
    byProject[p.project]++;
  } else {
    rec.error = JSON.stringify(r.body || {}).slice(0, 300);
    bad.push(rec);
  }
}

const meta0 = (plans[0] || { json: {} }).json;
return [{ json: {
  planned: plans.length,
  written_ok: ok.length,
  write_failed: bad.length,
  returned_mismatch: mismatch.length,
  by_project: byProject,
  count_before: meta0.count_before || {},
  excluded_projects: meta0.excluded_projects || [],
  failures: bad,
  mismatches: mismatch,
  written: ok
}}];
